require_once __DIR__.'/../includes/functions.php';require_login();require_once __DIR__.'/../config/database.php';$roleId=(int)($_GET['id']??0);$st=$pdo->prepare('SELECT * FROM job_roles WHERE job_role_id=? AND is_active=1');$st->execute([$roleId]);$role=$st->fetch();if(!$role){flash('Career role not found.','error');redirect('careers/index.php');}
$st=$pdo->prepare('SELECT s.skill_id,s.skill_name,s.description,sc.category_name,rs.required_level,rs.importance_weight FROM role_skills rs JOIN skills s ON s.skill_id=rs.skill_id LEFT JOIN skill_categories sc ON sc.category_id=s.category_id WHERE rs.job_role_id=? ORDER BY rs.importance_weight DESC,s.skill_name');$st->execute([$roleId]);$skills=$st->fetchAll();
$st=$pdo->prepare('SELECT saved_role_id FROM saved_job_roles WHERE user_id=? AND job_role_id=?');$st->execute([(int)current_user()['user_id'],$roleId]);$isSaved=(bool)$st->fetchColumn();$icons=['Cloud Engineer'=>'☁','AI / Machine Learning Engineer'=>'✧','Frontend Developer'=>'◫','Backend Developer'=>'⌘','Cybersecurity Analyst'=>'⬡','DevOps Engineer'=>'⟳'];
$pageTitle=$role['role_name'];$active='careers';include __DIR__.'/../includes/header.php';?>
<main class="main"><div class="container section-sm"><div class="role-detail-head"><span class="pill" style="background:#ffffff22;color:#fff"><?=h($role['career_field'])?></span><div class="row" style="margin-top:13px"><span style="font-size:35px"><?=h($icons[$role['role_name']]??'✦')?></span><div><h1><?=h($role['role_name'])?></h1><p><?=h($role['short_description'])?></p></div></div><div class="row" style="margin-top:20px;flex-wrap:wrap"><a class="btn" style="background:#fff;color:#234da9" href="<?=h(url('assessment/start.php?role_id='.$roleId))?>">Assess my skills →</a><form method="post" action="<?=h(url('careers/save.php'))?>"><?=csrf_field()?><input type="hidden" name="job_role_id" value="<?=$roleId?>"><button class="btn btn-outline" type="submit" style="background:#ffffff15;color:#fff;border-color:#ffffff55"><?=$isSaved?'Remove saved role':'☆ Save career'?></button></form></div></div>
<div class="grid grid-2" style="margin-top:20px;align-items:start"><section class="card card-pad"><div class="panel-title"><h3>Skills commonly associated with this role</h3><span class="pill pill-blue"><?=count($skills)?> skills</span></div><?php if($skills):foreach($skills as $s):?><div class="skill-row"><div><h4><?=h($s['skill_name'])?></h4><p><?=h($s['description'])?></p><span class="tiny muted"><?=h($s['category_name']??'General')?></span></div><div style="text-align:right"><span class="pill pill-amber">Target: <?=h(level_label((int)$s['required_level']))?></span><div class="tiny muted" style="margin-top:5px">Importance ×<?=number_format((float)$s['importance_weight'],1)?></div></div></div><?php endforeach;else:?><p class="muted small">No skills have been mapped to this role yet.</p><?php endif;?></section><aside class="stack"><section class="card card-pad"><h3 class="h3">What this role involves</h3><p class="muted small" style="line-height:1.8"><?=nl2br(h($role['responsibilities']?:$role['short_description']))?></p></section><section class="card card-pad"><h3 class="h3">How assessment works</h3><p class="muted small">Rate your current proficiency for each mapped skill. The platform calculates a weighted skill-coverage indicator. It is a planning aid, not a hiring or placement prediction.</p><a class="btn btn-primary btn-block" href="<?=h(url('assessment/start.php?role_id='.$roleId))?>">Start skill assessment →</a></section></aside></div></div></main><?php include __DIR__.'/../includes/footer.php';?>
